import fs from 'node:fs';import {build} from 'esbuild';import {execFileSync} from 'node:child_process';
const dir='tools/review/perspectives-visual-r1';const rows=[];for(const entry of ['assets/customer-ui/js/public-index-copy.js','assets/customer-ui/js/shell.js','assets/customer-ui/surfaces/perspectives-visual-r1.css']){const start=new Date().toISOString();try{const result=await build({entryPoints:[entry],bundle:true,platform:'browser',format:'esm',outdir:dir+'/compiled',metafile:true,logLevel:'silent'});rows.push({command:'esbuild '+entry+' --bundle --platform=browser --format=esm --outdir='+dir+'/compiled',exitCode:0,start,inputs:Object.keys(result.metafile.inputs).length,outputs:Object.keys(result.metafile.outputs),warnings:result.warnings});}catch(e){rows.push({command:'esbuild '+entry,exitCode:1,error:String(e)});}}fs.writeFileSync(dir+'/build-log.json',JSON.stringify({head:execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim(),scope:'ISOLATED_PRESENTATION_BUILD_ONLY_NO_SHARED_PAGES_OUTPUT',rows,paidCalls:0,deletions:0,deployments:0},null,2)+'\n');console.log(rows.map(r=>({command:r.command,exit:r.exitCode})));
